AssistantMessageToolRequest(name='create', tool_call_id='tooluse_25BvLaRu0ySR7zJstNvTGc', arguments={'file_text': 'const quizForm = document.getElementById('quiz-form');
const successMessage = document.getElementById('success-message');

// Expected answers (based on correct knowledge)
const answers = {
  q1: ['javascript', 'typescript'], // Web development languages
  q2: ['java', 'csharp'],            // Statically typed
  q3: ['rust', 'go']                 // Memory-safe design focus
};

quizForm.addEventListener('submit', handleSubmit);

function handleSubmit(e) {
  e.preventDefault();

  // Reset previous error states
  clearErrors();

  // Check each question
  let isValid = true;
  Object.keys(answers).forEach(questionId => {
    const isAnswered = isQuestionAnswered(questionId);
    if (!isAnswered) {
      isValid = false;
      showError(questionId, 'This question is required. Please select at least one answer.');
    }
  });

  if (isValid) {
    // Show success message
    successMessage.hidden = false;
    successMessage.focus();

    // Log submitted answers (for demonstration)
    const formData = new FormData(quizForm);
    const submitted = {};
    formData.forEach((value, key) => {
      if (!submitted[key]) submitted[key] = [];
      submitted[key].push(value);
    });
    console.log('Submitted answers:', submitted);
  } else {
    // Focus on the first unanswered question
    const firstUnanswered = Object.keys(answers).find(
      qId => !isQuestionAnswered(qId)
    );
    if (firstUnanswered) {
      const firstCheckbox = document.querySelector(`input[name="${firstUnanswered}"]`);
      firstCheckbox?.focus();
    }
  }
}

function isQuestionAnswered(questionId) {
  const checkboxes = document.querySelectorAll(`input[name="${questionId}"]`);
  return Array.from(checkboxes).some(cb => cb.checked);
}

function showError(questionId, message) {
  const errorElement = document.getElementById(`${questionId}-error`);
  if (errorElement) {
    errorElement.textContent = `Error: ${message}`;
    errorElement.hidden = false;
  }
}

function clearErrors() {
  document.querySelectorAll('.error-text').forEach(el => {
    el.textContent = '';
